 for item in select value from jsonb_array_elements($facts$[{"slug":"issuance-of-a-new-work-permit-golden-visa-holders","sourceUrl":"https://mohre.gov.ae/en/services/work-permits-of-golden-visa-holders-2022","arabicSourceUrl":"https://mohre.gov.ae/ar/services/work-permits-of-golden-visa-holders-2022","requirements":["صورة شخصية ملونة بخلفية بيضاء.","نسخة جواز السفر والإقامة الذهبية، وكلاهما ساري المفعول.","عرض العمل المعتمد من الوزارة وموقع من صاحب العمل والعامل.","المؤهل الدراسي المصدق بحسب المستوى المهاري: شهادة جامعية للمستويين 1–2، ودبلوم فأعلى للمستويين 3–4، وثانوية عامة للمستوى 5؛ لا تطلب شهادة للمستويات 6–9. يربط المصدر وصف العامل الماهر بالمؤهل وراتب لا يقل عن 4000 درهم.","ترخيص مزاولة المهنة من الجهة المختصة إذا كانت المهنة منظمة وتتطلب ترخيصًا."],"fees":"الرسم الاتحادي المنشور: 50 درهمًا. لا تضيف قناة الموقع أو التطبيق رسم خدمة للوزارة فوق الرسوم الحكومية. الضرائب ورسوم التحصيل غير مشمولة. عمولة مركز الأعمال، عند استخدامه، منفصلة وبحد أقصى 72 درهمًا؛ ليست رسمًا حكوميًا ولا رسم حسام بحر.","duration":"يومان عمل لإتمام الخدمة. صلاحية تصريح العمل سنتان؛ الصلاحية ليست مدة المعالجة.","conditions":"العمر 18 سنة فأكثر؛ إقامة ذهبية سارية وعدم وجود تصريح عمل فعال. يجب توافق المهنة مع نشاط المنشأة، وسريان رخصتها وعدم وجود مخالفات توقف نشاطها، وتقديم الطلب من المخول بالتوقيع. لا يشترط ضمان مصرفي أو تأمين أو حصة إلكترونية لهذا التصريح. المهن المنظمة تحتاج ترخيص مزاولة وفق تشريعاتها.","specialCases":"بطاقة الخدمة الرسمية المطابقة.","officialSteps":["تسجيل الدخول بالهوية الرقمية عبر قناة معتمدة.","استكمال بيانات الطلب ومراجعة البيانات المسترجعة وإرفاق المستندات.","مراجعة تفاصيل الطلب وتسديد الرسوم المقررة.","إصدار التصريح بعد استيفاء المتطلبات؛ قد تطلب الوزارة استكمال نواقص."],"emirate":"اتحادي","executionUrl":null,"excludedJurisdictions":[]},{"slug":"issuance-of-a-new-work-permit-mission-work-permit","sourceUrl":"https://www.mohre.gov.ae/en/services/mission-work-permit-2022","arabicSourceUrl":"https://www.mohre.gov.ae/ar/services/mission-work-permit-2022","requirements"